/**
 * @name Command injection in subprocess calls
 * @description Subprocess calls with untrusted input may allow command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection-flow
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Remote sources
    source instanceof RemoteFlowSource
    or
    // Function parameters that could be controlled by callers
    exists(Function f, Parameter p |
      source.(DataFlow::ParameterNode).getParameter() = p and
      p = f.getAnArg() and
      not p.getName().matches("self")
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command execution with potential untrusted input from $@.", source.getNode(), "this source"

/**
 * @name Path traversal via user input
 * @description File operations using untrusted input without validation
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-flow
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource or
    // Check for function parameters as potential user input
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "File operation using path from $@.", source.getNode(), "user input"

/**
 * @name Code injection via compile
 * @description Using compile, eval or exec with untrusted input can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/code-injection-compile-packaging
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module CodeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode or
    source instanceof DataFlow::LocalSourceNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call.getFunction().(DataFlow::AttrRead).getAttributeName() = "compile" and
      sink = call.getArg(0)
    )
  }
}

module CodeInjectionFlow = TaintTracking::Global<CodeInjectionConfig>;
import CodeInjectionFlow::PathGraph

from CodeInjectionFlow::PathNode source, CodeInjectionFlow::PathNode sink
where CodeInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code compilation from $@.", source.getNode(), "potentially untrusted input"

/**
 * @name Unsafe eval/literal_eval with user input
 * @description Using ast.literal_eval with user input can lead to code execution
 * @kind path-problem
 * @problem.severity high
 * @id py/unsafe-literal-eval-flow
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module UnsafeEvalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Function parameters that could be user-controlled
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("ast").getMember("literal_eval").getACall() or
        call = API::builtin("eval").getACall() or
        call = API::builtin("exec").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module UnsafeEvalFlow = TaintTracking::Global<UnsafeEvalConfig>;
import UnsafeEvalFlow::PathGraph

from UnsafeEvalFlow::PathNode source, UnsafeEvalFlow::PathNode sink
where UnsafeEvalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe eval/literal_eval from $@.", source.getNode(), "user-controlled parameter"
